import{_ as r,o as e,c as t,a2 as o}from"./chunks/framework.DDEX3mHW.js";const p=JSON.parse('{"title":"对接中转","description":"","frontmatter":{},"headers":[],"relativePath":"guide/relay.md","filePath":"guide/relay.md","lastUpdated":1792201523000}'),l={name:"guide/relay.md"};function i(n,a,s,d,h,c){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="对接中转" tabindex="-1">对接中转 <a class="header-anchor" href="#对接中转" aria-label="Permalink to &quot;对接中转&quot;">​</a></h1><p><strong>中转</strong> 页的 <strong>线路</strong> 标签按落地列出所有中转线路，点一个落地 → 选择隧道即可添加（也可以在落地页点入站 → <strong>中转</strong>）。隧道在 <strong>中转</strong> 页的 <strong>隧道</strong> 标签创建，入口是中转机；原来的“规则”在 <strong>规则</strong> 标签。</p><h2 id="对接方式" tabindex="-1">对接方式 <a class="header-anchor" href="#对接方式" aria-label="Permalink to &quot;对接方式&quot;">​</a></h2><ul><li><strong>端口转发</strong>：中转机直接把流量转发到落地机的公网地址</li><li><strong>隧道转发（出口为落地机）</strong>：流量经隧道到落地机，再转发到 <code>127.0.0.1:入站端口</code>。入站可以只监听 <code>127.0.0.1</code>，落地机不对外暴露端口</li><li><strong>隧道转发（出口为其他节点）</strong>：用于“前置 → IX → 落地”这类多跳线路。流量经隧道到出口节点（如 IX），再由出口节点连接落地机的公网地址。只需要中转、不需要加密时，隧道协议选 TCP 即可</li></ul><h2 id="前置-→-ix-→-落地" tabindex="-1">前置 → IX → 落地 <a class="header-anchor" href="#前置-→-ix-→-落地" aria-label="Permalink to &quot;前置 → IX → 落地&quot;">​</a></h2><ol><li>节点页添加前置、IX、落地三台机器，都装好 agent</li><li>隧道页新建一条“隧道转发”：入口选前置，出口选 IX，协议按需选择（不需要加密就选 TCP）</li><li>点击落地机上的入站 → <strong>中转</strong>，选这条隧道</li><li>如果 IX 只允许前置访问，在 IX 的防火墙里放行前置的地址即可；落地机可以开启入站白名单，只放行 IX</li></ol><p>订阅里的中转线路使用前置的地址和入口端口。</p><h2 id="订阅与清理" tabindex="-1">订阅与清理 <a class="header-anchor" href="#订阅与清理" aria-label="Permalink to &quot;订阅与清理&quot;">​</a></h2><p>中转线路会自动加入订阅，名称为“隧道名 → 入站名”。删除中转、入站或内核时，相关的转发会一并清理。</p><h2 id="获取真实客户端-ip-仅-xray" tabindex="-1">获取真实客户端 IP（仅 Xray） <a class="header-anchor" href="#获取真实客户端-ip-仅-xray" aria-label="Permalink to &quot;获取真实客户端 IP（仅 Xray）&quot;">​</a></h2><p>开启后，中转转发会附带 PROXY protocol，落地机内核日志里能看到客户端真实 IP。开启后直连将无法使用，入站会自动变为“仅中转”。</p><h2 id="入站白名单" tabindex="-1">入站白名单 <a class="header-anchor" href="#入站白名单" aria-label="Permalink to &quot;入站白名单&quot;">​</a></h2><p>开启后，该入站端口只放行本机、直接连接落地机的节点（端口转发的中转机、隧道转发的出口节点）和你填写的额外 IP / 网段，其余来源直接丢弃，只影响这一个端口。中转增删时白名单会自动更新。</p>',13)])])}const u=r(l,[["render",i]]);export{p as __pageData,u as default};
